const buttons=[...document.querySelectorAll('[data-filter]')];
function filter(kind){for(const b of buttons){const active=b.dataset.filter===kind;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));}let count=0;for(const card of document.querySelectorAll('[data-kind]')){card.hidden=kind!=='All'&&card.dataset.kind!==kind;if(!card.hidden)count++;}document.querySelector('#result-count').textContent=`${count} notes`;}
buttons.forEach(b=>b.addEventListener('click',()=>filter(b.dataset.filter)));
document.querySelectorAll('[data-category]').forEach(a=>a.addEventListener('click',()=>filter(a.dataset.category)));
const dialog=document.querySelector('#article-dialog');
document.querySelectorAll('[data-story]').forEach(b=>b.addEventListener('click',()=>{const entry=entries[b.dataset.story];document.querySelector('#article-kind').textContent=entry.kind;document.querySelector('#article-title').textContent=entry.title;document.querySelector('#article-body').innerHTML=entry.body;dialog.showModal();dialog.scrollTop=0;}));
document.querySelector('.close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();});

// Beer detail pages can link straight to their notebook story.
function openLinkedStory(){
 const slug=location.hash.replace(/^#story-/, '');
 if(!location.hash.startsWith('#story-'))return;
 const key=slug==='broken-rake'?'story':slug;
 const entry=entries[key];if(!entry)return;
 document.querySelector('.notebook').open=true;
 filter('Stories');
 document.querySelector('#journal').scrollIntoView();
 document.querySelector('#article-kind').textContent=entry.kind;
 document.querySelector('#article-title').textContent=entry.title;
 document.querySelector('#article-body').innerHTML=entry.body;
 if(!dialog.open)dialog.showModal();dialog.scrollTop=0;
}
window.addEventListener('hashchange',openLinkedStory);
openLinkedStory();
